import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { ReceptionistService } from '../../../core/services/receptionist.service';
import { PatientService } from '../../../core/services/patient.service';
import { Department, Doctor, Patient, Token } from '../../../core/models';

@Component({
  selector: 'app-generate-token',
  templateUrl: './generate-token.component.html'
})
export class GenerateTokenComponent implements OnInit {

  patients: Patient[] = [];
  departments: Department[] = [];
  doctors: Doctor[] = [];
  filteredDoctors: Doctor[] = [];

  form: FormGroup;
  loading = false;
  success = '';
  error = '';
  generatedToken: Token | null = null;

  constructor(
    private fb: FormBuilder,
    private receptionistService: ReceptionistService,
    private patientService: PatientService
  ) {
    this.form = this.fb.group({
      patientId:    [null, Validators.required],
      departmentId: [null, Validators.required],
      doctorId:     [null, Validators.required],
      priority:     ['NORMAL', Validators.required]
    });
  }

  ngOnInit(): void {
    this.receptionistService.getPatients().subscribe(p => this.patients = p);
    this.patientService.getPublicDepartments().subscribe(d => this.departments = d);
    this.patientService.getPublicDoctors().subscribe(d => this.doctors = d);

    this.form.get('departmentId')?.valueChanges.subscribe(deptId => {
      this.filteredDoctors = this.doctors.filter(d => d.department.id === +deptId && d.available);
      this.form.get('doctorId')?.reset();
    });
  }

  submit(): void {
    if (this.form.invalid) return;
    this.loading = true;
    this.error = '';
    this.success = '';
    this.generatedToken = null;

    const { departmentId, ...payload } = this.form.value;

    this.receptionistService.generateToken(payload).subscribe({
      next: token => {
        this.generatedToken = token;
        this.success = `Token ${token.tokenNumber} generated successfully.`;
        this.form.reset({ priority: 'NORMAL' });
        this.loading = false;
      },
      error: err => {
        this.error = err.error?.message ?? 'Failed to generate token.';
        this.loading = false;
      }
    });
  }
}
<div class="page-header">
  <h2>Generate Token</h2>
  <p>Assign a queue token to a registered patient</p>
</div>

<div class="card" style="max-width:520px;">
  <div *ngIf="success" class="alert alert-success">{{ success }}</div>
  <div *ngIf="error"   class="alert alert-danger">{{ error }}</div>

  <div *ngIf="generatedToken" class="card" style="background:#f0f9ff;border:1px solid #bee3f8;text-align:center;margin-bottom:16px;">
    <p style="font-size:13px;color:#2b6cb0;">Token Generated</p>
    <div class="token-number">{{ generatedToken.tokenNumber }}</div>
    <p style="margin-top:8px;color:#4a5568;">{{ generatedToken.patientName }} → Dr. {{ generatedToken.doctorName }}</p>
    <p><span class="badge badge-{{ generatedToken.priority.toLowerCase() }}">{{ generatedToken.priority }}</span></p>
  </div>

  <form [formGroup]="form" (ngSubmit)="submit()">
    <div class="form-group">
      <label>Patient *</label>
      <select formControlName="patientId">
        <option [ngValue]="null" disabled>Select patient</option>
        <option *ngFor="let p of patients" [value]="p.id">
          {{ p.name }} ({{ p.phone }})
        </option>
      </select>
    </div>
    <div class="form-group">
      <label>Department *</label>
      <select formControlName="departmentId">
        <option [ngValue]="null" disabled>Select department</option>
        <option *ngFor="let d of departments" [value]="d.id">{{ d.name }}</option>
      </select>
    </div>
    <div class="form-group">
      <label>Doctor *</label>
      <select formControlName="doctorId" [disabled]="!form.get('departmentId')?.value">
        <option [ngValue]="null" disabled>Select doctor</option>
        <option *ngFor="let d of filteredDoctors" [value]="d.id">
          {{ d.name }} ({{ d.specialization }})
        </option>
      </select>
    </div>
    <div class="form-group">
      <label>Priority *</label>
      <select formControlName="priority">
        <option value="NORMAL">Normal</option>
        <option value="URGENT">Urgent</option>
        <option value="EMERGENCY">Emergency</option>
      </select>
    </div>
    <button class="btn btn-primary" [disabled]="loading">
      {{ loading ? 'Generating...' : 'Generate Token' }}
    </button>
  </form>
</div>
